import { streamSimple } from "/home/runner/work/pit/pit/node_modules/@earendil-works/pi-ai/dist/api/anthropic-messages.js";
import { normalizeContext } from "/home/runner/work/pit/pit/node_modules/@earendil-works/pi-ai/dist/utils/transcript.js";

const model = {
  id: "aws/anthropic/bedrock-claude-opus-5-5", name: "Opus 5.5", api: "anthropic-messages", provider: "nvidia",
  baseUrl: "https://inference-api.nvidia.com", reasoning: true, input: ["text", "image"],
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: 1050000, maxTokens: 128000,
  compat: { forceAdaptiveThinking: true },
};
const apiKey = process.env.INPUT_API_KEY;
const tools = [{ name: "echo", description: "Echoes text.", parameters: { type: "object", properties: { text: { type: "string" } }, required: ["text"] } }];
const systemPrompt = "You are a careful assistant. Always reason step by step before calling tools.";

async function ask(messages, label) {
  const stream = streamSimple(model, normalizeContext({ systemPrompt, messages, tools }), { apiKey, reasoning: "high", maxTokens: 8000 });
  const result = await stream.result();
  const kinds = result.content.map((b) => b.type + (b.type === "thinking" ? `(sig:${Boolean(b.thinkingSignature)})` : ""));
  console.log(label, "->", result.stopReason, result.errorMessage ?? "", JSON.stringify(kinds), JSON.stringify(result.content.filter((b) => b.type === "text").map((b) => b.text)).slice(0, 200));
  return result;
}

const user = (text) => ({ role: "user", content: text, timestamp: Date.now() });
const first = user("Work out the sum of the first 12 primes, check it twice, then call echo once with that number as text, and answer with what echo returned.");
let call;
for (let attempt = 0; attempt < 3; attempt++) {
  call = await ask([first], `tool call #${attempt}`);
  if (call.content.some((b) => b.type === "thinking" && b.thinkingSignature) && call.content.some((b) => b.type === "toolCall")) break;
}
const toolCall = call.content.find((b) => b.type === "toolCall");
if (!toolCall) throw new Error("no tool call");
const result = { role: "toolResult", toolCallId: toolCall.id, toolName: "echo", content: [{ type: "text", text: toolCall.arguments.text }], isError: false, timestamp: Date.now() };
const answer = await ask([first, call, result], "answer");
const note = (id) => `[Pit: collapsed echo call · ok · ~40 tokens · originals: session.inspectEntry("${id}"), session.inspectEntry("${id + 1}")]`;
const collapse = (message, id) => ({ ...message, content: [...message.content.filter((b) => b.type !== "toolCall"), { type: "text", text: note(id) }], stopReason: "stop" });
console.log("collapsed blocks", JSON.stringify(collapse(call, 2).content.map((b) => b.type)));
const followUp = user("In one sentence: what did the earlier run do?");
await ask([first, collapse(call, 2), answer, followUp], "collapsed(thinking+sig)+answer");
await ask([first, collapse(call, 2), collapse(call, 4), answer, followUp], "two collapsed(thinking+sig)+answer");
